package dev.agenttrust.core;
import java.util.*;import java.time.*;import java.sql.Timestamp;import java.util.function.Supplier;
import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class EvaluationRecentTest {
 final RunService runs=mock(RunService.class);final JdbcTemplate jdbc=mock(JdbcTemplate.class);final EvaluationRecent recent=new EvaluationRecent(runs,jdbc);
 final DemoUser user=new DemoUser("fixture","unused",UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"viewer");
 final Instant end=Instant.parse("2026-11-12T07:00:00.123456Z");
 Map<String,Object> fixture(){return new HashMap<>(Map.of("completed",10L,"errors",2L,"unknown",3L,"terminal",20L,"invalid",0L,"window_start",Timestamp.from(end.minusSeconds(86400)),"observed_at",Timestamp.from(end)));}
 void result(Map<String,Object> row){when(runs.scoped(eq(user),any())).thenAnswer(c->((Supplier<?>)c.getArgument(1)).get());when(jdbc.queryForMap(anyString(),eq(user.organizationId()),eq(user.projectId()))).thenReturn(row);}
 @Test void databaseClockAndCompletionTimestampDefineTheWindowInOneScopedRead(){result(fixture());var v=recent.read(user);assertEquals(10,v.completedCount());assertEquals(2,v.executionErrorCount());assertEquals(3,v.unknownCompletionTimeCount());assertEquals(end,v.observedAt());assertEquals(end.minusSeconds(86400),v.windowStart());assertFalse(v.deploymentAuthority());assertEquals(user.projectId(),v.projectId());verify(runs).scoped(eq(user),any());verify(jdbc).queryForMap(EvaluationRecent.SQL,user.organizationId(),user.projectId());verifyNoMoreInteractions(jdbc);assertTrue(EvaluationRecent.SQL.contains("statement_timestamp()"));assertTrue(EvaluationRecent.SQL.contains("completed_at BETWEEN"));assertTrue(EvaluationRecent.SQL.contains("state='failed' AND completed_at BETWEEN"));assertTrue(EvaluationRecent.SQL.contains("completed_at IS NULL"));assertTrue(EvaluationRecent.SQL.contains("CROSS JOIN LATERAL"));assertFalse(EvaluationRecent.SQL.contains("GROUP BY"));assertFalse(EvaluationRecent.SQL.contains("created_at BETWEEN"));assertTrue(EvaluationRecent.SQL.contains("r.organization_id=? AND r.project_id=?"));}
 @Test void verifiedEmptyAndAllUnknownRemainDifferent(){var row=fixture();for(String key:List.of("completed","errors","unknown","terminal"))row.put(key,0L);result(row);assertEquals(0,recent.read(user).completedCount());row.put("unknown",20L);row.put("terminal",20L);assertEquals(20,recent.read(user).unknownCompletionTimeCount());}
 @Test void invalidPartialNumbersAndArithmeticFailClosed(){for(String key:fixture().keySet()){var row=fixture();row.remove(key);result(row);assertThrows(IllegalStateException.class,()->recent.read(user));}for(Object invalid:List.of(-1L,0.5,Double.NaN,9_007_199_254_740_992L,"unknown")){var row=fixture();row.put("completed",invalid);result(row);assertThrows(IllegalStateException.class,()->recent.read(user));}for(var change:List.of(Map.entry("errors",11L),Map.entry("terminal",12L),Map.entry("invalid",1L))){var row=fixture();row.put(change.getKey(),change.getValue());result(row);assertThrows(IllegalStateException.class,()->recent.read(user));}}
 @Test void exactMicrosecondWindowCannotBeReplacedByRoundedOrApplicationTimes(){for(Instant bad:List.of(end.minusSeconds(86400).plusNanos(1000),end.minusSeconds(86400).plusSeconds(1),end.minusSeconds(86400).plusNanos(1))){var row=fixture();row.put("window_start",Timestamp.from(bad));result(row);assertThrows(IllegalStateException.class,()->recent.read(user));}}
 @Test void unauthorizedAndUnknownRoleNeverQuery(){assertEquals(401,assertThrows(ResponseStatusException.class,()->recent.read(null)).getStatusCode().value());assertEquals(403,assertThrows(ResponseStatusException.class,()->recent.read(new DemoUser("fixture","unused",user.organizationId(),user.projectId(),user.actorId(),"other"))).getStatusCode().value());verifyNoInteractions(runs,jdbc);}
}
